from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        # Using OrderedDict to maintain insertion order and easily remove LRU items
        self.cache = OrderedDict()

    def get(self, key, default=None):
        if key not in self.cache:
            # If default is None, return -1 as per original test expectation
            return default if default is not None else -1

        # Move the accessed item to the end (most recently used)
        value = self.cache.pop(key)
        self.cache[key] = value
        return value

    def put(self, key, value):
        if key in self.cache:
            # If key exists, update value and move to end
            self.cache.pop(key)
        elif len(self.cache) >= self.capacity:
            # If cache is full, remove the first item (least recently used)
            self.cache.popitem(last=False)
        # Add the new item or updated item to the end
        self.cache[key] = value

    # For test_evicts_oldest: assertNotIn(key, c) implies iteration over keys
    def __iter__(self):
        return iter(self.cache.keys())

    # For test_update_does_not_evict: len(c)
    def __len__(self):
        return len(self.cache)
